        b = await p.chromium.launch(); pg = await b.new_page()
        await pg.set_content(Path(path).read_text(), wait_until="domcontentloaded")
        await pg.wait_for_timeout(1300)
        r = await pg.evaluate(JS, {"prefix": "e"})
